  "Project saved with {count} validation issue.": {"fr":"Projet enregistré avec {count} problème de validation.","es":"Proyecto guardado con {count} problema de validación.","zh-Hans":"项目已保存，但存在 {count} 个验证问题。","ja":"プロジェクトは {count} 個の検証問題とともに保存されました。","ko":"{count}개의 유효성 검사 문제로 프로젝트가 저장되었습니다.","ar":"تم حفظ المشروع مع مشكلة التحقق من صحة {count}."},
  "Project saved with {count} validation issues.": {"fr":"Projet enregistré avec {count} problèmes de validation.","es":"Proyecto guardado con {count} problemas de validación.","zh-Hans":"已保存项目，但存在 {count} 个验证问题。","ja":"プロジェクトは {count} 個の検証問題とともに保存されました。","ko":"{count}개의 유효성 검사 문제로 프로젝트가 저장되었습니다.","ar":"تم حفظ المشروع مع وجود {count} مشكلات في التحقق من الصحة."},
  "Project: {projectName}": {"fr":"Projet : {projectName}","es":"Proyecto: {projectName}","zh-Hans":"项目：{projectName}","ja":"プロジェクト: {projectName}","ko":"프로젝트: {projectName}","ar":"المشروع: {projectName}"},
  "Projects": {"fr":"Projets","es":"Proyectos","zh-Hans":"项目","ja":"プロジェクト","ko":"프로젝트","ar":"المشاريع"},
  "Recent projects": {"fr":"Projets récents","es":"Proyectos recientes","zh-Hans":"最近的项目","ja":"最近のプロジェクト","ko":"최근 프로젝트","ar":"المشاريع الأخيرة"},
  "Recent projects refreshed.": {"fr":"Projets récents rafraîchis.","es":"Proyectos recientes actualizados.","zh-Hans":"最近的项目刷新了。","ja":"最近のプロジェクトが更新されました。","ko":"최근 프로젝트가 새로 고쳐졌습니다.","ar":"المشاريع الأخيرة منتعشة."},
  "Redo": {"fr":"Refaire","es":"Rehacer","zh-Hans":"重做","ja":"やり直し","ko":"다시 실행","ar":"إعادة"},
