  "{projectName} - MAGE2 Editor [Unsaved]": {"fr":"{projectName} - Éditeur MAGE2 [Non enregistré]","es":"{projectName} - Editor MAGE2 [sin guardar]","zh-Hans":"{projectName} - MAGE2 编辑器 [未保存]","ja":"{projectName} - MAGE2 エディター [未保存]","ko":"{projectName} - MAGE2 편집기 [저장되지 않음]","ar":"{projectName} - محرر MAGE2 [غير محفوظ]"},
  "{projectName} - MAGE2 Editor": {"fr":"{projectName} - Éditeur MAGE2","es":"{projectName} - Editor de MAGE2","zh-Hans":"{projectName} - MAGE2 编辑器","ja":"{projectName} - MAGE2 エディター","ko":"{projectName} - MAGE2 편집기","ar":"{projectName} - محرر MAGE2"},
